/* eslint-disable max-len, max-params */

'use strict';

// MODULES //

var copyIndexed = require( '@stdlib/array/base/copy-indexed' );
var incrementOffsets = require( '@stdlib/ndarray/base/kernels/utils/increment-offsets' );
var setViewOffsets = require( '@stdlib/ndarray/base/set-descriptor-offsets' );
var offsets = require( '@stdlib/ndarray/base/offsets' );
var wrap = require( './callback_wrapper.js' );


// MAIN //

/**
* Applies a one-dimensional strided array function to an input ndarray according to a callback function.
*
* @private
* @param {Function} fcn - wrapper for a one-dimensional strided array function
* @param {Array<Object>} arrays - ndarray descriptors
* @param {ndarrayLike} ref - original input ndarray provided to a callback function
* @param {Array<Object>} views - initialized ndarray descriptors representing subarray views
* @param {Array<integer>} shape - loop dimensions
* @param {Array<integer>} stridesX - loop dimension strides for the input ndarray
* @param {Object} strategyX - strategy for marshaling data to and from an input ndarray view
* @param {NonNegativeIntegerArray} ibuf - workspace for storing iteration indices
* @param {NonNegativeIntegerArray} ldims - list of loop dimensions
* @param {NonNegativeIntegerArray} cdims - list of "core" dimensions
* @param {Options} opts - function options
* @param {boolean} hasOpts - boolean indicating whether to pass an options argument to a strided array function
* @param {Function} clbk - callback function
* @param {*} thisArg - callback execution context
* @returns {void}
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
* var zeros = require( '@stdlib/array/base/zeros' );
* var gfillBy = require( '@stdlib/blas/ext/base/ndarray/gfill-by' );
* var strategy = require( '@stdlib/ndarray/base/kernels/generic/unary-strided1d/strategy' );
*
* function clbk( value, idx ) {
*     return ( idx[ 0 ]*100 ) + ( idx[ 1 ]*10 ) + idx[ 2 ];
* }
*
* // Create a data buffer:
* var xbuf = new Float64Array( 12 );
*
* // Define the array shape:
* var xsh = [ 3, 2, 2 ];
*
* // Define the array strides:
* var sx = [ 4, 2, 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray descriptor:
* var x = {
*     'dtype': 'float64',
*     'data': xbuf,
*     'shape': xsh,
*     'strides': sx,
*     'offset': ox,
*     'order': 'row-major'
* };
*
* // Create an ndarray descriptor for the starting index (inclusive):
* var start = {
*     'dtype': 'float64',
*     'data': new Float64Array( [ 0.0 ] ),
*     'shape': [ 3 ],
*     'strides': [ 0 ],
*     'offset': 0,
*     'order': 'row-major'
* };
*
* // Create an ndarray descriptor for the ending index (exclusive):
* var end = {
*     'dtype': 'float64',
*     'data': new Float64Array( [ 4.0 ] ),
*     'shape': [ 3 ],
*     'strides': [ 0 ],
*     'offset': 0,
*     'order': 'row-major'
* };
*
* // Initialize ndarray descriptors representing subarray views:
* var views = [
*     {
*         'dtype': x.dtype,
*         'data': x.data,
*         'shape': [ 2, 2 ],
*         'strides': [ 2, 1 ],
*         'offset': x.offset,
*         'order': x.order
*     },
*     {
*         'dtype': start.dtype,
*         'data': start.data,
*         'shape': [],
*         'strides': [ 0 ],
*         'offset': start.offset,
*         'order': start.order
*     },
*     {
*         'dtype': end.dtype,
*         'data': end.data,
*         'shape': [],
*         'strides': [ 0 ],
*         'offset': end.offset,
*         'order': end.order
*     }
* ];
*
* // Resolve an input strategy when iterating over subarray views:
* var strategyX = strategy( views[ 0 ] );
*
* // Create a workspace array for storing iteration indices:
* var ibuf = zeros( xsh.length );
*
* // Define the loop and core dimensions:
* var ldims = [ 0 ];
* var cdims = [ 1, 2 ];
*
* // Apply strided function:
* kernel( gfillBy, [ x, start, end ], x, views, [ 3 ], [ 4 ], strategyX, ibuf, ldims, cdims, {}, false, clbk, {} );
*
* var arr = ndarray2array( x.data, x.shape, x.strides, x.offset, x.order );
* // returns [ [ [ 0.0, 1.0 ], [ 10.0, 11.0 ] ], [ [ 100.0, 101.0 ], [ 110.0, 111.0 ] ], [ [ 200.0, 201.0 ], [ 210.0, 211.0 ] ] ]
*/
function kernel( fcn, arrays, ref, views, shape, stridesX, strategyX, ibuf, ldims, cdims, opts, hasOpts, clbk, thisArg ) {
	var dv0;
	var S0;
	var iv;
	var i0;
	var v;
	var i;
	var f;

	// Note on variable naming convention: S#, dv#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	// Extract loop variables for purposes of loop interchange: dimensions and loop offset (pointer) increments...
	S0 = shape[ 0 ];
	dv0 = [
		stridesX[0]
	];
	for ( i = 1; i < arrays.length; i++ ) {
		dv0.push( arrays[i].strides[0] );
	}
	// Resolve a list of pointers to the first indexed elements in the respective ndarrays:
	iv = offsets( arrays );

	// Shallow copy the list of views to an internal array so that we can update with reshaped views without impacting the original list of views:
	v = copyIndexed( views );

	// Iterate over the loop dimensions...
	for ( i0 = 0; i0 < S0; i0++ ) {
		setViewOffsets( views, iv );
		v[ 0 ] = strategyX.input( views[ 0 ] );
		f = wrap( ref, views[ 0 ], ibuf, ldims, [ i0 ], cdims, clbk, thisArg );
		if ( hasOpts ) {
			fcn( v, opts, f );
		} else {
			fcn( v, f );
		}
		strategyX.output( views[ 0 ] );
		incrementOffsets( iv, dv0 );
	}
}


// EXPORTS //

module.exports = kernel;
